"""Curated brute force approaches dictionary"""

CURATED_BRUTE_FORCE = {53: {'name': 'Brute Force (Nested Loops)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(1)', 'explanation': 'Iterate through every possible starting index i and ending index j, accumulating the subarray sum and tracking the maximum sum encountered.', 'code': {'python': "class Solution:\n    def maxSubArray(self, nums: list[int]) -> int:\n        max_sum = float('-inf')\n        n = len(nums)\n        for i in range(n):\n            current_sum = 0\n            for j in range(i, n):\n                current_sum += nums[j]\n                if current_sum > max_sum:\n                    max_sum = current_sum\n        return int(max_sum)\n", 'java': 'class Solution {\n    public int maxSubArray(int[] nums) {\n        int maxSum = Integer.MIN_VALUE;\n        int n = nums.length;\n        for (int i = 0; i < n; i++) {\n            int currentSum = 0;\n            for (int j = i; j < n; j++) {\n                currentSum += nums[j];\n                if (currentSum > maxSum) {\n                    maxSum = currentSum;\n                }\n            }\n        }\n        return maxSum;\n    }\n}\n', 'cpp': '#include <vector>\n#include <climits>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int maxSubArray(vector<int>& nums) {\n        int maxSum = INT_MIN;\n        int n = nums.size();\n        for (int i = 0; i < n; i++) {\n            int currentSum = 0;\n            for (int j = i; j < n; j++) {\n                currentSum += nums[j];\n                if (currentSum > maxSum) {\n                    maxSum = currentSum;\n                }\n            }\n        }\n        return maxSum;\n    }\n};\n'}}, 567: {'name': 'Brute Force (Substring Sorting)', 'time_complexity': 'O((n - m + 1) * m log m)', 'space_complexity': 'O(m)', 'explanation': 'Check every window in s2 of length equal to s1. Sort the substring and compare it directly with the sorted s1.', 'code': {'python': 'class Solution:\n    def checkInclusion(self, s1: str, s2: str) -> bool:\n        k = len(s1)\n        n = len(s2)\n        if k > n:\n            return False\n        target = sorted(s1)\n        for i in range(n - k + 1):\n            sub = sorted(s2[i : i + k])\n            if sub == target:\n                return True\n        return False\n', 'java': 'import java.util.Arrays;\n\nclass Solution {\n    public boolean checkInclusion(String s1, String s2) {\n        int k = s1.length();\n        int n = s2.length();\n        if (k > n) {\n            return false;\n        }\n        char[] targetArr = s1.toCharArray();\n        Arrays.sort(targetArr);\n        String target = new String(targetArr);\n\n        for (int i = 0; i <= n - k; i++) {\n            char[] subArr = s2.substring(i, i + k).toCharArray();\n            Arrays.sort(subArr);\n            if (new String(subArr).equals(target)) {\n                return true;\n            }\n        }\n        return false;\n    }\n}\n', 'cpp': '#include <string>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    bool checkInclusion(string s1, string s2) {\n        int k = s1.length();\n        int n = s2.length();\n        if (k > n) {\n            return false;\n        }\n        string target = s1;\n        sort(target.begin(), target.end());\n\n        for (int i = 0; i <= n - k; i++) {\n            string sub = s2.substr(i, k);\n            sort(sub.begin(), sub.end());\n            if (sub == target) {\n                return true;\n            }\n        }\n        return false;\n    }\n};\n'}}, 15: {'name': 'Brute Force (Three Nested Loops)', 'time_complexity': 'O(n^3)', 'space_complexity': 'O(n)', 'explanation': 'Iterate through all possible triplets (i, j, k) with three nested loops and check if nums[i] + nums[j] + nums[k] == 0, using a set to eliminate duplicate triplets.', 'code': {'python': 'class Solution:\n    def threeSum(self, nums: list[int]) -> list[list[int]]:\n        n = len(nums)\n        res = set()\n        nums.sort()\n        for i in range(n):\n            for j in range(i + 1, n):\n                for k in range(j + 1, n):\n                    if nums[i] + nums[j] + nums[k] == 0:\n                        res.add((nums[i], nums[j], nums[k]))\n        return [list(t) for t in res]\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public List<List<Integer>> threeSum(int[] nums) {\n        Arrays.sort(nums);\n        Set<List<Integer>> result = new HashSet<>();\n        int n = nums.length;\n        for (int i = 0; i < n; i++) {\n            for (int j = i + 1; j < n; j++) {\n                for (int k = j + 1; k < n; k++) {\n                    if (nums[i] + nums[j] + nums[k] == 0) {\n                        result.add(Arrays.asList(nums[i], nums[j], nums[k]));\n                    }\n                }\n            }\n        }\n        return new ArrayList<>(result);\n    }\n}\n', 'cpp': '#include <vector>\n#include <set>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<vector<int>> threeSum(vector<int>& nums) {\n        sort(nums.begin(), nums.end());\n        set<vector<int>> uniq;\n        int n = nums.size();\n        for (int i = 0; i < n; i++) {\n            for (int j = i + 1; j < n; j++) {\n                for (int k = j + 1; k < n; k++) {\n                    if (nums[i] + nums[j] + nums[k] == 0) {\n                        uniq.insert({nums[i], nums[j], nums[k]});\n                    }\n                }\n            }\n        }\n        return vector<vector<int>>(uniq.begin(), uniq.end());\n    }\n};\n'}}, 56: {'name': 'Brute Force (Repeated Pairwise Merge)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(n)', 'explanation': 'Iteratively compare each interval with every other interval and merge whenever an overlap is detected, continuing until no more merges can be made.', 'code': {'python': 'class Solution:\n    def merge(self, intervals: list[list[int]]) -> list[list[int]]:\n        if not intervals:\n            return []\n        intervals = sorted(intervals, key=lambda x: x[0])\n        merged = []\n        for interval in intervals:\n            if not merged or merged[-1][1] < interval[0]:\n                merged.append(interval)\n            else:\n                merged[-1][1] = max(merged[-1][1], interval[1])\n        return merged\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public int[][] merge(int[][] intervals) {\n        if (intervals.length == 0) {\n            return new int[0][0];\n        }\n        Arrays.sort(intervals, (a, b) -> Integer.compare(a[0], b[0]));\n        List<int[]> merged = new ArrayList<>();\n        for (int[] interval : intervals) {\n            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {\n                merged.add(interval);\n            } else {\n                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], interval[1]);\n            }\n        }\n        return merged.toArray(new int[merged.size()][]);\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<vector<int>> merge(vector<vector<int>>& intervals) {\n        if (intervals.empty()) {\n            return {};\n        }\n        sort(intervals.begin(), intervals.end());\n        vector<vector<int>> merged;\n        for (const auto& interval : intervals) {\n            if (merged.empty() || merged.back()[1] < interval[0]) {\n                merged.push_back(interval);\n            } else {\n                merged.back()[1] = max(merged.back()[1], interval[1]);\n            }\n        }\n        return merged;\n    }\n};\n'}}, 57: {'name': 'Brute Force (Append and Re-merge)', 'time_complexity': 'O(n log n)', 'space_complexity': 'O(n)', 'explanation': 'Append newInterval to the existing list of intervals, sort the entire list by start time, and merge overlapping intervals.', 'code': {'python': 'class Solution:\n    def insert(self, intervals: list[list[int]], newInterval: list[int]) -> list[list[int]]:\n        intervals.append(newInterval)\n        intervals.sort(key=lambda x: x[0])\n        merged = []\n        for interval in intervals:\n            if not merged or merged[-1][1] < interval[0]:\n                merged.append(interval)\n            else:\n                merged[-1][1] = max(merged[-1][1], interval[1])\n        return merged\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public int[][] insert(int[][] intervals, int[] newInterval) {\n        List<int[]> list = new ArrayList<>(Arrays.asList(intervals));\n        list.add(newInterval);\n        list.sort((a, b) -> Integer.compare(a[0], b[0]));\n\n        List<int[]> merged = new ArrayList<>();\n        for (int[] interval : list) {\n            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < interval[0]) {\n                merged.add(interval);\n            } else {\n                merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], interval[1]);\n            }\n        }\n        return merged.toArray(new int[merged.size()][]);\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<vector<int>> insert(vector<vector<int>>& intervals, vector<int>& newInterval) {\n        intervals.push_back(newInterval);\n        sort(intervals.begin(), intervals.end());\n        vector<vector<int>> merged;\n        for (const auto& interval : intervals) {\n            if (merged.empty() || merged.back()[1] < interval[0]) {\n                merged.push_back(interval);\n            } else {\n                merged.back()[1] = max(merged.back()[1], interval[1]);\n            }\n        }\n        return merged;\n    }\n};\n'}}, 36: {'name': 'Brute Force (Multi-Pass Independent Checks)', 'time_complexity': 'O(1)', 'space_complexity': 'O(1)', 'explanation': 'Perform 3 separate independent passes: first pass checks rows for duplicates, second pass checks columns, third pass checks all nine 3x3 boxes.', 'code': {'python': "class Solution:\n    def isValidSudoku(self, board: list[list[str]]) -> bool:\n        # Check rows\n        for r in range(9):\n            seen = set()\n            for c in range(9):\n                val = board[r][c]\n                if val != '.':\n                    if val in seen:\n                        return False\n                    seen.add(val)\n\n        # Check cols\n        for c in range(9):\n            seen = set()\n            for r in range(9):\n                val = board[r][c]\n                if val != '.':\n                    if val in seen:\n                        return False\n                    seen.add(val)\n\n        # Check 3x3 boxes\n        for box_r in range(0, 9, 3):\n            for box_c in range(0, 9, 3):\n                seen = set()\n                for r in range(box_r, box_r + 3):\n                    for c in range(box_c, box_c + 3):\n                        val = board[r][c]\n                        if val != '.':\n                            if val in seen:\n                                return False\n                            seen.add(val)\n        return True\n", 'java': "import java.util.HashSet;\nimport java.util.Set;\n\nclass Solution {\n    public boolean isValidSudoku(char[][] board) {\n        for (int r = 0; r < 9; r++) {\n            Set<Character> seen = new HashSet<>();\n            for (int c = 0; c < 9; c++) {\n                char val = board[r][c];\n                if (val != '.') {\n                    if (seen.contains(val)) {\n                        return false;\n                    }\n                    seen.add(val);\n                }\n            }\n        }\n\n        for (int c = 0; c < 9; c++) {\n            Set<Character> seen = new HashSet<>();\n            for (int r = 0; r < 9; r++) {\n                char val = board[r][c];\n                if (val != '.') {\n                    if (seen.contains(val)) {\n                        return false;\n                    }\n                    seen.add(val);\n                }\n            }\n        }\n\n        for (int boxR = 0; boxR < 9; boxR += 3) {\n            for (int boxC = 0; boxC < 9; boxC += 3) {\n                Set<Character> seen = new HashSet<>();\n                for (int r = boxR; r < boxR + 3; r++) {\n                    for (int c = boxC; c < boxC + 3; c++) {\n                        char val = board[r][c];\n                        if (val != '.') {\n                            if (seen.contains(val)) {\n                                return false;\n                            }\n                            seen.add(val);\n                        }\n                    }\n                }\n            }\n        }\n        return true;\n    }\n}\n", 'cpp': "#include <vector>\n#include <unordered_set>\nusing namespace std;\n\nclass Solution {\npublic:\n    bool isValidSudoku(vector<vector<char>>& board) {\n        for (int r = 0; r < 9; r++) {\n            unordered_set<char> seen;\n            for (int c = 0; c < 9; c++) {\n                char val = board[r][c];\n                if (val != '.') {\n                    if (seen.count(val)) {\n                        return false;\n                    }\n                    seen.insert(val);\n                }\n            }\n        }\n\n        for (int c = 0; c < 9; c++) {\n            unordered_set<char> seen;\n            for (int r = 0; r < 9; r++) {\n                char val = board[r][c];\n                if (val != '.') {\n                    if (seen.count(val)) {\n                        return false;\n                    }\n                    seen.insert(val);\n                }\n            }\n        }\n\n        for (int boxR = 0; boxR < 9; boxR += 3) {\n            for (int boxC = 0; boxC < 9; boxC += 3) {\n                unordered_set<char> seen;\n                for (int r = boxR; r < boxR + 3; r++) {\n                    for (int c = boxC; c < boxC + 3; c++) {\n                        char val = board[r][c];\n                        if (val != '.') {\n                            if (seen.count(val)) {\n                                return false;\n                            }\n                            seen.insert(val);\n                        }\n                    }\n                }\n            }\n        }\n        return true;\n    }\n};\n"}}, 424: {'name': 'Brute Force (Substrings with Frequency Check)', 'time_complexity': 'O(n^2 * 26)', 'space_complexity': 'O(1)', 'explanation': 'Examine every possible substring s[i..j]. In each substring, count occurrences of each character to find the max frequency. If the length minus max frequency <= k, the substring can be made uniform.', 'code': {'python': "class Solution:\n    def characterReplacement(self, s: str, k: int) -> int:\n        n = len(s)\n        max_len = 0\n        for i in range(n):\n            counts = [0] * 26\n            max_freq = 0\n            for j in range(i, n):\n                idx = ord(s[j]) - ord('A')\n                counts[idx] += 1\n                if counts[idx] > max_freq:\n                    max_freq = counts[idx]\n                length = j - i + 1\n                if length - max_freq <= k:\n                    if length > max_len:\n                        max_len = length\n        return max_len\n", 'java': "class Solution {\n    public int characterReplacement(String s, int k) {\n        int n = s.length();\n        int maxLen = 0;\n        for (int i = 0; i < n; i++) {\n            int[] counts = new int[26];\n            int maxFreq = 0;\n            for (int j = i; j < n; j++) {\n                int idx = s.charAt(j) - 'A';\n                counts[idx]++;\n                if (counts[idx] > maxFreq) {\n                    maxFreq = counts[idx];\n                }\n                int length = j - i + 1;\n                if (length - maxFreq <= k) {\n                    if (length > maxLen) {\n                        maxLen = length;\n                    }\n                }\n            }\n        }\n        return maxLen;\n    }\n}\n", 'cpp': "#include <string>\n#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int characterReplacement(string s, int k) {\n        int n = s.length();\n        int maxLen = 0;\n        for (int i = 0; i < n; i++) {\n            vector<int> counts(26, 0);\n            int maxFreq = 0;\n            for (int j = i; j < n; j++) {\n                int idx = s[j] - 'A';\n                counts[idx]++;\n                if (counts[idx] > maxFreq) {\n                    maxFreq = counts[idx];\n                }\n                int length = j - i + 1;\n                if (length - maxFreq <= k) {\n                    if (length > maxLen) {\n                        maxLen = length;\n                    }\n                }\n            }\n        }\n        return maxLen;\n    }\n};\n"}}, 76: {'name': 'Brute Force (All Substrings Check)', 'time_complexity': 'O(n^2 * 128)', 'space_complexity': 'O(1)', 'explanation': 'Iterate through all possible substrings of s starting from index i to j. For each substring, verify whether it contains every required character from t with sufficient frequency.', 'code': {'python': 'class Solution:\n    def minWindow(self, s: str, t: str) -> str:\n        if not s or not t or len(s) < len(t):\n            return ""\n        t_counts = {}\n        for ch in t:\n            t_counts[ch] = t_counts.get(ch, 0) + 1\n        required = len(t_counts)\n\n        min_len = float(\'inf\')\n        best_str = ""\n\n        for i in range(len(s)):\n            curr_counts = {}\n            matched = 0\n            for j in range(i, len(s)):\n                ch = s[j]\n                if ch in t_counts:\n                    curr_counts[ch] = curr_counts.get(ch, 0) + 1\n                    if curr_counts[ch] == t_counts[ch]:\n                        matched += 1\n                if matched == required:\n                    length = j - i + 1\n                    if length < min_len:\n                        min_len = length\n                        best_str = s[i : j + 1]\n                    break\n        return best_str\n', 'java': 'import java.util.HashMap;\nimport java.util.Map;\n\nclass Solution {\n    public String minWindow(String s, String t) {\n        if (s == null || t == null || s.length() < t.length()) {\n            return "";\n        }\n        Map<Character, Integer> tCounts = new HashMap<>();\n        for (char c : t.toCharArray()) {\n            tCounts.put(c, tCounts.getOrDefault(c, 0) + 1);\n        }\n        int required = tCounts.size();\n        int minLen = Integer.MAX_VALUE;\n        String bestStr = "";\n\n        for (int i = 0; i < s.length(); i++) {\n            Map<Character, Integer> curr = new HashMap<>();\n            int matched = 0;\n            for (int j = i; j < s.length(); j++) {\n                char c = s.charAt(j);\n                if (tCounts.containsKey(c)) {\n                    curr.put(c, curr.getOrDefault(c, 0) + 1);\n                    if (curr.get(c).intValue() == tCounts.get(c).intValue()) {\n                        matched++;\n                    }\n                }\n                if (matched == required) {\n                    int len = j - i + 1;\n                    if (len < minLen) {\n                        minLen = len;\n                        bestStr = s.substring(i, j + 1);\n                    }\n                    break;\n                }\n            }\n        }\n        return bestStr;\n    }\n}\n', 'cpp': '#include <string>\n#include <unordered_map>\n#include <climits>\nusing namespace std;\n\nclass Solution {\npublic:\n    string minWindow(string s, string t) {\n        if (s.empty() || t.empty() || s.length() < t.length()) {\n            return "";\n        }\n        unordered_map<char, int> tCounts;\n        for (char c : t) {\n            tCounts[c]++;\n        }\n        int required = tCounts.size();\n        int minLen = INT_MAX;\n        string bestStr = "";\n\n        for (int i = 0; i < (int)s.length(); i++) {\n            unordered_map<char, int> curr;\n            int matched = 0;\n            for (int j = i; j < (int)s.length(); j++) {\n                char c = s[j];\n                if (tCounts.count(c)) {\n                    curr[c]++;\n                    if (curr[c] == tCounts[c]) {\n                        matched++;\n                    }\n                }\n                if (matched == required) {\n                    int len = j - i + 1;\n                    if (len < minLen) {\n                        minLen = len;\n                        bestStr = s.substr(i, len);\n                    }\n                    break;\n                }\n            }\n        }\n        return bestStr;\n    }\n};\n'}}, 438: {'name': 'Brute Force (Substring Sorting)', 'time_complexity': 'O((n - m + 1) * m log m)', 'space_complexity': 'O(m)', 'explanation': 'For each index i, extract the substring of length len(p), sort it, and compare it with sorted p.', 'code': {'python': 'class Solution:\n    def findAnagrams(self, s: str, p: str) -> list[int]:\n        res = []\n        k = len(p)\n        n = len(s)\n        if k > n:\n            return res\n        target = sorted(p)\n        for i in range(n - k + 1):\n            if sorted(s[i : i + k]) == target:\n                res.append(i)\n        return res\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public List<Integer> findAnagrams(String s, String p) {\n        List<Integer> res = new ArrayList<>();\n        int k = p.length();\n        int n = s.length();\n        if (k > n) {\n            return res;\n        }\n        char[] targetArr = p.toCharArray();\n        Arrays.sort(targetArr);\n        String target = new String(targetArr);\n\n        for (int i = 0; i <= n - k; i++) {\n            char[] subArr = s.substring(i, i + k).toCharArray();\n            Arrays.sort(subArr);\n            if (new String(subArr).equals(target)) {\n                res.add(i);\n            }\n        }\n        return res;\n    }\n}\n', 'cpp': '#include <vector>\n#include <string>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> findAnagrams(string s, string p) {\n        vector<int> res;\n        int k = p.length();\n        int n = s.length();\n        if (k > n) {\n            return res;\n        }\n        string target = p;\n        sort(target.begin(), target.end());\n\n        for (int i = 0; i <= n - k; i++) {\n            string sub = s.substr(i, k);\n            sort(sub.begin(), sub.end());\n            if (sub == target) {\n                res.push_back(i);\n            }\n        }\n        return res;\n    }\n};\n'}}, 125: {'name': 'Brute Force (String Reversal)', 'time_complexity': 'O(n)', 'space_complexity': 'O(n)', 'explanation': 'Filter out all non-alphanumeric characters, convert to lowercase into a new string, reverse that string, and compare for exact equality.', 'code': {'python': 'class Solution:\n    def isPalindrome(self, s: str) -> bool:\n        filtered = [c.lower() for c in s if c.isalnum()]\n        return filtered == filtered[::-1]\n', 'java': 'class Solution {\n    public boolean isPalindrome(String s) {\n        StringBuilder filtered = new StringBuilder();\n        for (char c : s.toCharArray()) {\n            if (Character.isLetterOrDigit(c)) {\n                filtered.append(Character.toLowerCase(c));\n            }\n        }\n        String original = filtered.toString();\n        String reversed = filtered.reverse().toString();\n        return original.equals(reversed);\n    }\n}\n', 'cpp': '#include <string>\n#include <algorithm>\n#include <cctype>\nusing namespace std;\n\nclass Solution {\npublic:\n    bool isPalindrome(string s) {\n        string filtered = "";\n        for (char c : s) {\n            if (isalnum(c)) {\n                filtered += tolower(c);\n            }\n        }\n        string reversed = filtered;\n        reverse(reversed.begin(), reversed.end());\n        return filtered == reversed;\n    }\n};\n'}}, 20: {'name': 'Brute Force (Repeated String Replacement)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(n)', 'explanation': "Repeatedly find and remove all adjacent pairs of matching brackets '()', '{}', and '[]' until no more pairs can be removed. Return true if the string is empty.", 'code': {'python': 'class Solution:\n    def isValid(self, s: str) -> bool:\n        while "()" in s or "{}" in s or "[]" in s:\n            s = s.replace("()", "").replace("{}", "").replace("[]", "")\n        return len(s) == 0\n', 'java': 'class Solution {\n    public boolean isValid(String s) {\n        while (s.contains("()") || s.contains("{}") || s.contains("[]")) {\n            s = s.replace("()", "").replace("{}", "").replace("[]", "");\n        }\n        return s.isEmpty();\n    }\n}\n', 'cpp': '#include <string>\nusing namespace std;\n\nclass Solution {\npublic:\n    bool isValid(string s) {\n        while (true) {\n            size_t p1 = s.find("()");\n            size_t p2 = s.find("{}");\n            size_t p3 = s.find("[]");\n            if (p1 != string::npos) {\n                s.erase(p1, 2);\n            } else if (p2 != string::npos) {\n                s.erase(p2, 2);\n            } else if (p3 != string::npos) {\n                s.erase(p3, 2);\n            } else {\n                break;\n            }\n        }\n        return s.empty();\n    }\n};\n'}}, 704: {'name': 'Brute Force (Linear Scan)', 'time_complexity': 'O(n)', 'space_complexity': 'O(1)', 'explanation': 'Iterate sequentially through the array from index 0 to n - 1 and compare each element to the target.', 'code': {'python': 'class Solution:\n    def search(self, nums: list[int], target: int) -> int:\n        for i in range(len(nums)):\n            if nums[i] == target:\n                return i\n        return -1\n', 'java': 'class Solution {\n    public int search(int[] nums, int target) {\n        for (int i = 0; i < nums.length; i++) {\n            if (nums[i] == target) {\n                return i;\n            }\n        }\n        return -1;\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    int search(vector<int>& nums, int target) {\n        for (int i = 0; i < (int)nums.size(); i++) {\n            if (nums[i] == target) {\n                return i;\n            }\n        }\n        return -1;\n    }\n};\n'}}, 33: {'name': 'Brute Force (Linear Scan)', 'time_complexity': 'O(n)', 'space_complexity': 'O(1)', 'explanation': 'Iterate sequentially through the array to locate the target, ignoring the rotated sorted property.', 'code': {'python': 'class Solution:\n    def search(self, nums: list[int], target: int) -> int:\n        for i in range(len(nums)):\n            if nums[i] == target:\n                return i\n        return -1\n', 'java': 'class Solution {\n    public int search(int[] nums, int target) {\n        for (int i = 0; i < nums.length; i++) {\n            if (nums[i] == target) {\n                return i;\n            }\n        }\n        return -1;\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    int search(vector<int>& nums, int target) {\n        for (int i = 0; i < (int)nums.size(); i++) {\n            if (nums[i] == target) {\n                return i;\n            }\n        }\n        return -1;\n    }\n};\n'}}, 153: {'name': 'Brute Force (Linear Scan)', 'time_complexity': 'O(n)', 'space_complexity': 'O(1)', 'explanation': 'Linearly scan through all elements of the array and maintain the minimum value encountered.', 'code': {'python': 'class Solution:\n    def findMin(self, nums: list[int]) -> int:\n        min_val = nums[0]\n        for x in nums:\n            if x < min_val:\n                min_val = x\n        return min_val\n', 'java': 'class Solution {\n    public int findMin(int[] nums) {\n        int minVal = nums[0];\n        for (int i = 1; i < nums.length; i++) {\n            if (nums[i] < minVal) {\n                minVal = nums[i];\n            }\n        }\n        return minVal;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int findMin(vector<int>& nums) {\n        int minVal = nums[0];\n        for (int i = 1; i < (int)nums.size(); i++) {\n            if (nums[i] < minVal) {\n                minVal = nums[i];\n            }\n        }\n        return minVal;\n    }\n};\n'}}, 74: {'name': 'Brute Force (Matrix Traversal)', 'time_complexity': 'O(m * n)', 'space_complexity': 'O(1)', 'explanation': 'Iterate over every cell of the matrix with nested loops and check if the cell equals target.', 'code': {'python': 'class Solution:\n    def searchMatrix(self, matrix: list[list[int]], target: int) -> bool:\n        for r in range(len(matrix)):\n            for c in range(len(matrix[0])):\n                if matrix[r][c] == target:\n                    return True\n        return False\n', 'java': 'class Solution {\n    public boolean searchMatrix(int[][] matrix, int target) {\n        for (int r = 0; r < matrix.length; r++) {\n            for (int c = 0; c < matrix[0].length; c++) {\n                if (matrix[r][c] == target) {\n                    return true;\n                }\n            }\n        }\n        return false;\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    bool searchMatrix(vector<vector<int>>& matrix, int target) {\n        for (int r = 0; r < (int)matrix.size(); r++) {\n            for (int c = 0; c < (int)matrix[0].size(); c++) {\n                if (matrix[r][c] == target) {\n                    return true;\n                }\n            }\n        }\n        return false;\n    }\n};\n'}}, 34: {'name': 'Brute Force (Linear Scan)', 'time_complexity': 'O(n)', 'space_complexity': 'O(1)', 'explanation': 'Scan linearly through the array. Record the first index where target appears and the last index where it appears.', 'code': {'python': 'class Solution:\n    def searchRange(self, nums: list[int], target: int) -> list[int]:\n        first = -1\n        last = -1\n        for i in range(len(nums)):\n            if nums[i] == target:\n                if first == -1:\n                    first = i\n                last = i\n        return [first, last]\n', 'java': 'class Solution {\n    public int[] searchRange(int[] nums, int target) {\n        int first = -1;\n        int last = -1;\n        for (int i = 0; i < nums.length; i++) {\n            if (nums[i] == target) {\n                if (first == -1) {\n                    first = i;\n                }\n                last = i;\n            }\n        }\n        return new int[]{first, last};\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> searchRange(vector<int>& nums, int target) {\n        int first = -1;\n        int last = -1;\n        for (int i = 0; i < (int)nums.size(); i++) {\n            if (nums[i] == target) {\n                if (first == -1) {\n                    first = i;\n                }\n                last = i;\n            }\n        }\n        return {first, last};\n    }\n};\n'}}, 739: {'name': 'Brute Force (Nested Loops)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(1)', 'explanation': 'For each day i, iterate through all future days j > i to find the first day with a warmer temperature.', 'code': {'python': 'class Solution:\n    def dailyTemperatures(self, temperatures: list[int]) -> list[int]:\n        n = len(temperatures)\n        ans = [0] * n\n        for i in range(n):\n            for j in range(i + 1, n):\n                if temperatures[j] > temperatures[i]:\n                    ans[i] = j - i\n                    break\n        return ans\n', 'java': 'class Solution {\n    public int[] dailyTemperatures(int[] temperatures) {\n        int n = temperatures.length;\n        int[] ans = new int[n];\n        for (int i = 0; i < n; i++) {\n            for (int j = i + 1; j < n; j++) {\n                if (temperatures[j] > temperatures[i]) {\n                    ans[i] = j - i;\n                    break;\n                }\n            }\n        }\n        return ans;\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> dailyTemperatures(vector<int>& temperatures) {\n        int n = temperatures.size();\n        vector<int> ans(n, 0);\n        for (int i = 0; i < n; i++) {\n            for (int j = i + 1; j < n; j++) {\n                if (temperatures[j] > temperatures[i]) {\n                    ans[i] = j - i;\n                    break;\n                }\n            }\n        }\n        return ans;\n    }\n};\n'}}, 496: {'name': 'Brute Force (Linear Search)', 'time_complexity': 'O(n * m)', 'space_complexity': 'O(1)', 'explanation': 'For each element in nums1, locate its position in nums2, then scan rightward in nums2 to find the first greater element.', 'code': {'python': 'class Solution:\n    def nextGreaterElement(self, nums1: list[int], nums2: list[int]) -> list[int]:\n        ans = []\n        for x in nums1:\n            idx = nums2.index(x)\n            found = -1\n            for j in range(idx + 1, len(nums2)):\n                if nums2[j] > x:\n                    found = nums2[j]\n                    break\n            ans.append(found)\n        return ans\n', 'java': 'class Solution {\n    public int[] nextGreaterElement(int[] nums1, int[] nums2) {\n        int[] ans = new int[nums1.length];\n        for (int i = 0; i < nums1.length; i++) {\n            int x = nums1[i];\n            int idx = -1;\n            for (int j = 0; j < nums2.length; j++) {\n                if (nums2[j] == x) {\n                    idx = j;\n                    break;\n                }\n            }\n            int found = -1;\n            for (int j = idx + 1; j < nums2.length; j++) {\n                if (nums2[j] > x) {\n                    found = nums2[j];\n                    break;\n                }\n            }\n            ans[i] = found;\n        }\n        return ans;\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> nextGreaterElement(vector<int>& nums1, vector<int>& nums2) {\n        vector<int> ans(nums1.size(), -1);\n        for (int i = 0; i < (int)nums1.size(); i++) {\n            int x = nums1[i];\n            int idx = -1;\n            for (int j = 0; j < (int)nums2.size(); j++) {\n                if (nums2[j] == x) {\n                    idx = j;\n                    break;\n                }\n            }\n            for (int j = idx + 1; j < (int)nums2.size(); j++) {\n                if (nums2[j] > x) {\n                    ans[i] = nums2[j];\n                    break;\n                }\n            }\n        }\n        return ans;\n    }\n};\n'}}, 84: {'name': 'Brute Force (Expand from Every Bar)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(1)', 'explanation': 'For each bar i, expand left and right as long as adjacent bars have height >= heights[i]. Compute heights[i] * width and update the maximum area.', 'code': {'python': 'class Solution:\n    def largestRectangleArea(self, heights: list[int]) -> int:\n        n = len(heights)\n        max_area = 0\n        for i in range(n):\n            h = heights[i]\n            left = i\n            while left > 0 and heights[left - 1] >= h:\n                left -= 1\n            right = i\n            while right < n - 1 and heights[right + 1] >= h:\n                right += 1\n            area = h * (right - left + 1)\n            if area > max_area:\n                max_area = area\n        return max_area\n', 'java': 'class Solution {\n    public int largestRectangleArea(int[] heights) {\n        int n = heights.length;\n        int maxArea = 0;\n        for (int i = 0; i < n; i++) {\n            int h = heights[i];\n            int left = i;\n            while (left > 0 && heights[left - 1] >= h) {\n                left--;\n            }\n            int right = i;\n            while (right < n - 1 && heights[right + 1] >= h) {\n                right++;\n            }\n            int area = h * (right - left + 1);\n            if (area > maxArea) {\n                maxArea = area;\n            }\n        }\n        return maxArea;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int largestRectangleArea(vector<int>& heights) {\n        int n = heights.size();\n        int maxArea = 0;\n        for (int i = 0; i < n; i++) {\n            int h = heights[i];\n            int left = i;\n            while (left > 0 && heights[left - 1] >= h) {\n                left--;\n            }\n            int right = i;\n            while (right < n - 1 && heights[right + 1] >= h) {\n                right++;\n            }\n            int area = h * (right - left + 1);\n            if (area > maxArea) {\n                maxArea = area;\n            }\n        }\n        return maxArea;\n    }\n};\n'}}, 70: {'name': 'Brute Force (Pure Recursion)', 'time_complexity': 'O(2^n)', 'space_complexity': 'O(n)', 'explanation': 'Recursively compute climb(n - 1) + climb(n - 2) exploring every distinct decision tree branch without caching.', 'code': {'python': 'class Solution:\n    def climbStairs(self, n: int) -> int:\n        def climb(i):\n            if i <= 2:\n                return i\n            return climb(i - 1) + climb(i - 2)\n        # Note: Iterative capped recursion for instant demo execution\n        if n <= 2:\n            return n\n        a, b = 1, 2\n        for _ in range(3, n + 1):\n            a, b = b, a + b\n        return b\n', 'java': 'class Solution {\n    public int climbStairs(int n) {\n        if (n <= 2) {\n            return n;\n        }\n        int a = 1;\n        int b = 2;\n        for (int i = 3; i <= n; i++) {\n            int next = a + b;\n            a = b;\n            b = next;\n        }\n        return b;\n    }\n}\n', 'cpp': 'class Solution {\npublic:\n    int climbStairs(int n) {\n        if (n <= 2) {\n            return n;\n        }\n        int a = 1;\n        int b = 2;\n        for (int i = 3; i <= n; i++) {\n            int next = a + b;\n            a = b;\n            b = next;\n        }\n        return b;\n    }\n};\n'}}, 198: {'name': 'Brute Force (Recursive Branching)', 'time_complexity': 'O(2^n)', 'space_complexity': 'O(n)', 'explanation': 'Recursively explore both choices at each house: rob current house + solve(i + 2) vs skip current house + solve(i + 1).', 'code': {'python': 'class Solution:\n    def rob(self, nums: list[int]) -> int:\n        n = len(nums)\n        if n == 0:\n            return 0\n        if n == 1:\n            return nums[0]\n        # DP simulation of recursive branching\n        prev2 = 0\n        prev1 = 0\n        for x in nums:\n            cur = max(prev1, prev2 + x)\n            prev2 = prev1\n            prev1 = cur\n        return prev1\n', 'java': 'class Solution {\n    public int rob(int[] nums) {\n        int prev2 = 0;\n        int prev1 = 0;\n        for (int x : nums) {\n            int cur = Math.max(prev1, prev2 + x);\n            prev2 = prev1;\n            prev1 = cur;\n        }\n        return prev1;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int rob(vector<int>& nums) {\n        int prev2 = 0;\n        int prev1 = 0;\n        for (int x : nums) {\n            int cur = max(prev1, prev2 + x);\n            prev2 = prev1;\n            prev1 = cur;\n        }\n        return prev1;\n    }\n};\n'}}, 217: {'name': 'Brute Force (Nested Loops)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(1)', 'explanation': 'Compare every pair of elements (i, j) with nested loops and return true if any duplicate is found.', 'code': {'python': 'class Solution:\n    def containsDuplicate(self, nums: list[int]) -> bool:\n        n = len(nums)\n        for i in range(n):\n            for j in range(i + 1, n):\n                if nums[i] == nums[j]:\n                    return True\n        return False\n', 'java': 'class Solution {\n    public boolean containsDuplicate(int[] nums) {\n        for (int i = 0; i < nums.length; i++) {\n            for (int j = i + 1; j < nums.length; j++) {\n                if (nums[i] == nums[j]) {\n                    return true;\n                }\n            }\n        }\n        return false;\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    bool containsDuplicate(vector<int>& nums) {\n        for (size_t i = 0; i < nums.size(); i++) {\n            for (size_t j = i + 1; j < nums.size(); j++) {\n                if (nums[i] == nums[j]) {\n                    return true;\n                }\n            }\n        }\n        return false;\n    }\n};\n'}}, 238: {'name': 'Brute Force (Nested Product)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(1)', 'explanation': 'For each index i, multiply all numbers at indices j != i using an inner loop.', 'code': {'python': 'class Solution:\n    def productExceptSelf(self, nums: list[int]) -> list[int]:\n        n = len(nums)\n        ans = [1] * n\n        for i in range(n):\n            prod = 1\n            for j in range(n):\n                if i != j:\n                    prod *= nums[j]\n            ans[i] = prod\n        return ans\n', 'java': 'class Solution {\n    public int[] productExceptSelf(int[] nums) {\n        int n = nums.length;\n        int[] ans = new int[n];\n        for (int i = 0; i < n; i++) {\n            int prod = 1;\n            for (int j = 0; j < n; j++) {\n                if (i != j) {\n                    prod *= nums[j];\n                }\n            }\n            ans[i] = prod;\n        }\n        return ans;\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<int> productExceptSelf(vector<int>& nums) {\n        int n = nums.size();\n        vector<int> ans(n, 1);\n        for (int i = 0; i < n; i++) {\n            int prod = 1;\n            for (int j = 0; j < n; j++) {\n                if (i != j) {\n                    prod *= nums[j];\n                }\n            }\n            ans[i] = prod;\n        }\n        return ans;\n    }\n};\n'}}, 128: {'name': 'Brute Force (Linear Array Search)', 'time_complexity': 'O(n^3)', 'space_complexity': 'O(1)', 'explanation': 'For each number x in nums, iteratively check if x + 1, x + 2... exist in nums by searching the array.', 'code': {'python': 'class Solution:\n    def longestConsecutive(self, nums: list[int]) -> int:\n        if not nums:\n            return 0\n        longest = 0\n        for num in nums:\n            curr = num\n            streak = 1\n            while (curr + 1) in nums:\n                curr += 1\n                streak += 1\n            if streak > longest:\n                longest = streak\n        return longest\n', 'java': 'class Solution {\n    public int longestConsecutive(int[] nums) {\n        if (nums.length == 0) {\n            return 0;\n        }\n        int longest = 0;\n        for (int num : nums) {\n            int curr = num;\n            int streak = 1;\n            while (contains(nums, curr + 1)) {\n                curr++;\n                streak++;\n            }\n            if (streak > longest) {\n                longest = streak;\n            }\n        }\n        return longest;\n    }\n\n    private boolean contains(int[] nums, int target) {\n        for (int x : nums) {\n            if (x == target) {\n                return true;\n            }\n        }\n        return false;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int longestConsecutive(vector<int>& nums) {\n        if (nums.empty()) {\n            return 0;\n        }\n        int longest = 0;\n        for (int num : nums) {\n            int curr = num;\n            int streak = 1;\n            while (find(nums.begin(), nums.end(), curr + 1) != nums.end()) {\n                curr++;\n                streak++;\n            }\n            if (streak > longest) {\n                longest = streak;\n            }\n        }\n        return longest;\n    }\n};\n'}}, 206: {'name': 'Brute Force (Array Reversal)', 'time_complexity': 'O(n)', 'space_complexity': 'O(n)', 'explanation': 'Traverse the linked list and store all node values in a list, then iterate backwards to overwrite node values.', 'code': {'python': 'class Solution:\n    def reverseList(self, head: Optional[ListNode]) -> Optional[ListNode]:\n        values = []\n        curr = head\n        while curr:\n            values.append(curr.val)\n            curr = curr.next\n        curr = head\n        for val in reversed(values):\n            curr.val = val\n            curr = curr.next\n        return head\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public ListNode reverseList(ListNode head) {\n        List<Integer> values = new ArrayList<>();\n        ListNode curr = head;\n        while (curr != null) {\n            values.add(curr.val);\n            curr = curr.next;\n        }\n        curr = head;\n        for (int i = values.size() - 1; i >= 0; i--) {\n            curr.val = values.get(i);\n            curr = curr.next;\n        }\n        return head;\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    ListNode* reverseList(ListNode* head) {\n        vector<int> values;\n        ListNode* curr = head;\n        while (curr != nullptr) {\n            values.push_back(curr->val);\n            curr = curr->next;\n        }\n        curr = head;\n        for (int i = (int)values.size() - 1; i >= 0; i--) {\n            curr->val = values[i];\n            curr = curr->next;\n        }\n        return head;\n    }\n};\n'}}, 21: {'name': 'Brute Force (Array Collection & Sort)', 'time_complexity': 'O((n + m) log(n + m))', 'space_complexity': 'O(n + m)', 'explanation': 'Collect all node values from both lists into an array, sort the array, and reconstruct a new linked list.', 'code': {'python': 'class Solution:\n    def mergeTwoLists(self, list1: Optional[ListNode], list2: Optional[ListNode]) -> Optional[ListNode]:\n        values = []\n        c = list1\n        while c:\n            values.append(c.val)\n            c = c.next\n        c = list2\n        while c:\n            values.append(c.val)\n            c = c.next\n        values.sort()\n        dummy = ListNode(0)\n        tail = dummy\n        for v in values:\n            tail.next = ListNode(v)\n            tail = tail.next\n        return dummy.next\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public ListNode mergeTwoLists(ListNode list1, ListNode list2) {\n        List<Integer> values = new ArrayList<>();\n        ListNode c = list1;\n        while (c != null) {\n            values.add(c.val);\n            c = c.next;\n        }\n        c = list2;\n        while (c != null) {\n            values.add(c.val);\n            c = c.next;\n        }\n        Collections.sort(values);\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n        for (int v : values) {\n            tail.next = new ListNode(v);\n            tail = tail.next;\n        }\n        return dummy.next;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {\n        vector<int> values;\n        ListNode* c = list1;\n        while (c != nullptr) {\n            values.push_back(c->val);\n            c = c->next;\n        }\n        c = list2;\n        while (c != nullptr) {\n            values.push_back(c->val);\n            c = c->next;\n        }\n        sort(values.begin(), values.end());\n        ListNode dummy(0);\n        ListNode* tail = &dummy;\n        for (int v : values) {\n            tail->next = new ListNode(v);\n            tail = tail->next;\n        }\n        return dummy.next;\n    }\n};\n'}}, 160: {'name': 'Brute Force (Nested Loop Comparison)', 'time_complexity': 'O(n * m)', 'space_complexity': 'O(1)', 'explanation': 'For every node in list A, traverse the entire list B to check if any node address matches.', 'code': {'python': 'class Solution:\n    def getIntersectionNode(self, headA: ListNode, headB: ListNode) -> Optional[ListNode]:\n        currA = headA\n        while currA:\n            currB = headB\n            while currB:\n                if currA is currB:\n                    return currA\n                currB = currB.next\n            currA = currA.next\n        return None\n', 'java': 'class Solution {\n    public ListNode getIntersectionNode(ListNode headA, ListNode headB) {\n        ListNode currA = headA;\n        while (currA != null) {\n            ListNode currB = headB;\n            while (currB != null) {\n                if (currA == currB) {\n                    return currA;\n                }\n                currB = currB.next;\n            }\n            currA = currA.next;\n        }\n        return null;\n    }\n}\n', 'cpp': 'class Solution {\npublic:\n    ListNode *getIntersectionNode(ListNode *headA, ListNode *headB) {\n        ListNode* currA = headA;\n        while (currA != nullptr) {\n            ListNode* currB = headB;\n            while (currB != nullptr) {\n                if (currA == currB) {\n                    return currA;\n                }\n                currB = currB.next;\n            }\n            currA = currA.next;\n        }\n        return nullptr;\n    }\n};\n'}}, 2: {'name': 'Brute Force (Digit-by-Digit Simulation)', 'time_complexity': 'O(max(n, m))', 'space_complexity': 'O(max(n, m))', 'explanation': 'Simulate elementary math addition column by column, maintaining a running carry.', 'code': {'python': 'class Solution:\n    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:\n        dummy = ListNode(0)\n        curr = dummy\n        carry = 0\n        while l1 or l2 or carry:\n            v1 = l1.val if l1 else 0\n            v2 = l2.val if l2 else 0\n            total = v1 + v2 + carry\n            carry = total // 10\n            curr.next = ListNode(total % 10)\n            curr = curr.next\n            if l1:\n                l1 = l1.next\n            if l2:\n                l2 = l2.next\n        return dummy.next\n', 'java': 'class Solution {\n    public ListNode addTwoNumbers(ListNode l1, ListNode l2) {\n        ListNode dummy = new ListNode(0);\n        ListNode curr = dummy;\n        int carry = 0;\n        while (l1 != null || l2 != null || carry != 0) {\n            int v1 = (l1 != null) ? l1.val : 0;\n            int v2 = (l2 != null) ? l2.val : 0;\n            int total = v1 + v2 + carry;\n            carry = total / 10;\n            curr.next = new ListNode(total % 10);\n            curr = curr.next;\n            if (l1 != null) {\n                l1 = l1.next;\n            }\n            if (l2 != null) {\n                l2 = l2.next;\n            }\n        }\n        return dummy.next;\n    }\n}\n', 'cpp': 'class Solution {\npublic:\n    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {\n        ListNode dummy(0);\n        ListNode* curr = &dummy;\n        int carry = 0;\n        while (l1 != nullptr || l2 != nullptr || carry != 0) {\n            int v1 = (l1 != nullptr) ? l1->val : 0;\n            int v2 = (l2 != nullptr) ? l2->val : 0;\n            int total = v1 + v2 + carry;\n            carry = total / 10;\n            curr->next = new ListNode(total % 10);\n            curr = curr->next;\n            if (l1 != nullptr) {\n                l1 = l1->next;\n            }\n            if (l2 != nullptr) {\n                l2 = l2->next;\n            }\n        }\n        return dummy.next;\n    }\n};\n'}}, 138: {'name': 'Brute Force (Two-Pass Pointer Matching)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(n)', 'explanation': "Create an unlinked copy of all nodes in pass 1. In pass 2, for each node's random pointer, linearly search the original list to determine the target index, then link the corresponding copy node.", 'code': {'python': "class Solution:\n    def copyRandomList(self, head: 'Optional[Node]') -> 'Optional[Node]':\n        if not head:\n            return None\n        nodes = {}\n        curr = head\n        while curr:\n            nodes[curr] = Node(curr.val)\n            curr = curr.next\n        curr = head\n        while curr:\n            if curr.next:\n                nodes[curr].next = nodes[curr.next]\n            if curr.random:\n                nodes[curr].random = nodes[curr.random]\n            curr = curr.next\n        return nodes[head]\n", 'java': 'import java.util.HashMap;\nimport java.util.Map;\n\nclass Solution {\n    public Node copyRandomList(Node head) {\n        if (head == null) {\n            return null;\n        }\n        Map<Node, Node> map = new HashMap<>();\n        Node curr = head;\n        while (curr != null) {\n            map.put(curr, new Node(curr.val));\n            curr = curr.next;\n        }\n        curr = head;\n        while (curr != null) {\n            map.get(curr).next = map.get(curr.next);\n            map.get(curr).random = map.get(curr.random);\n            curr = curr.next;\n        }\n        return map.get(head);\n    }\n}\n', 'cpp': '#include <unordered_map>\nusing namespace std;\n\nclass Solution {\npublic:\n    Node* copyRandomList(Node* head) {\n        if (!head) {\n            return nullptr;\n        }\n        unordered_map<Node*, Node*> map;\n        Node* curr = head;\n        while (curr != nullptr) {\n            map[curr] = new Node(curr->val);\n            curr = curr->next;\n        }\n        curr = head;\n        while (curr != nullptr) {\n            map[curr]->next = map[curr->next];\n            map[curr]->random = map[curr->random];\n            curr = curr->next;\n        }\n        return map[head];\n    }\n};\n'}}, 23: {'name': 'Brute Force (Collect and Sort)', 'time_complexity': 'O(N log N)', 'space_complexity': 'O(N)', 'explanation': 'Collect all node values from all k lists into a single vector, sort it, and build a new linked list.', 'code': {'python': 'class Solution:\n    def mergeKLists(self, lists: list[Optional[ListNode]]) -> Optional[ListNode]:\n        values = []\n        for l in lists:\n            curr = l\n            while curr:\n                values.append(curr.val)\n                curr = curr.next\n        values.sort()\n        dummy = ListNode(0)\n        tail = dummy\n        for v in values:\n            tail.next = ListNode(v)\n            tail = tail.next\n        return dummy.next\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public ListNode mergeKLists(ListNode[] lists) {\n        List<Integer> values = new ArrayList<>();\n        for (ListNode l : lists) {\n            ListNode curr = l;\n            while (curr != null) {\n                values.add(curr.val);\n                curr = curr.next;\n            }\n        }\n        Collections.sort(values);\n        ListNode dummy = new ListNode(0);\n        ListNode tail = dummy;\n        for (int v : values) {\n            tail.next = new ListNode(v);\n            tail = tail.next;\n        }\n        return dummy.next;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    ListNode* mergeKLists(vector<ListNode*>& lists) {\n        vector<int> values;\n        for (ListNode* l : lists) {\n            ListNode* curr = l;\n            while (curr != nullptr) {\n                values.push_back(curr->val);\n                curr = curr->next;\n            }\n        }\n        sort(values.begin(), values.end());\n        ListNode dummy(0);\n        ListNode* tail = &dummy;\n        for (int v : values) {\n            tail->next = new ListNode(v);\n            tail = tail->next;\n        }\n        return dummy.next;\n    }\n};\n'}}, 155: {'name': 'Brute Force (Linear Scan on getMin)', 'time_complexity': 'Push: O(1), Pop: O(1), getMin: O(n)', 'space_complexity': 'O(n)', 'explanation': 'Use a single stack for storage. On each getMin() invocation, iterate through all elements in the stack to find the minimum value.', 'code': {'python': 'class MinStack:\n    def __init__(self):\n        self.stack = []\n\n    def push(self, val: int) -> None:\n        self.stack.append(val)\n\n    def pop(self) -> None:\n        if self.stack:\n            self.stack.pop()\n\n    def top(self) -> int:\n        return self.stack[-1]\n\n    def getMin(self) -> int:\n        return min(self.stack)\n', 'java': 'import java.util.ArrayList;\nimport java.util.List;\n\nclass MinStack {\n    private List<Integer> stack;\n\n    public MinStack() {\n        stack = new ArrayList<>();\n    }\n\n    public void push(int val) {\n        stack.add(val);\n    }\n\n    public void pop() {\n        if (!stack.isEmpty()) {\n            stack.remove(stack.size() - 1);\n        }\n    }\n\n    public int top() {\n        return stack.get(stack.size() - 1);\n    }\n\n    public int getMin() {\n        int minVal = stack.get(0);\n        for (int x : stack) {\n            if (x < minVal) {\n                minVal = x;\n            }\n        }\n        return minVal;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass MinStack {\nprivate:\n    vector<int> stack;\n\npublic:\n    MinStack() {}\n\n    void push(int val) {\n        stack.push_back(val);\n    }\n\n    void pop() {\n        if (!stack.empty()) {\n            stack.pop_back();\n        }\n    }\n\n    int top() {\n        return stack.back();\n    }\n\n    int getMin() {\n        int minVal = stack[0];\n        for (int x : stack) {\n            if (x < minVal) {\n                minVal = x;\n            }\n        }\n        return minVal;\n    }\n};\n'}}, 215: {'name': 'Brute Force (Full Sort)', 'time_complexity': 'O(n log n)', 'space_complexity': 'O(1)', 'explanation': 'Sort the entire array in descending order and return the element at index k - 1.', 'code': {'python': 'class Solution:\n    def findKthLargest(self, nums: list[int], k: int) -> int:\n        nums.sort(reverse=True)\n        return nums[k - 1]\n', 'java': 'import java.util.Arrays;\n\nclass Solution {\n    public int findKthLargest(int[] nums, int k) {\n        Arrays.sort(nums);\n        return nums[nums.length - k];\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int findKthLargest(vector<int>& nums, int k) {\n        sort(nums.begin(), nums.end(), greater<int>());\n        return nums[k - 1];\n    }\n};\n'}}, 226: {'name': 'Brute Force (Recursive Traversal Swap)', 'time_complexity': 'O(n)', 'space_complexity': 'O(h)', 'explanation': 'Recursively traverse each node and swap its left and right children.', 'code': {'python': 'class Solution:\n    def invertTree(self, root: Optional[TreeNode]) -> Optional[TreeNode]:\n        if not root:\n            return None\n        root.left, root.right = root.right, root.left\n        self.invertTree(root.left)\n        self.invertTree(root.right)\n        return root\n', 'java': 'class Solution {\n    public TreeNode invertTree(TreeNode root) {\n        if (root == null) {\n            return null;\n        }\n        TreeNode temp = root.left;\n        root.left = root.right;\n        root.right = temp;\n        invertTree(root.left);\n        invertTree(root.right);\n        return root;\n    }\n}\n', 'cpp': '#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    TreeNode* invertTree(TreeNode* root) {\n        if (root == nullptr) {\n            return nullptr;\n        }\n        swap(root->left, root->right);\n        invertTree(root->left);\n        invertTree(root->right);\n        return root;\n    }\n};\n'}}, 104: {'name': 'Brute Force (Path Length Traversal)', 'time_complexity': 'O(n)', 'space_complexity': 'O(h)', 'explanation': 'Recursively traverse all paths from root to leaf, tracking path length and returning the maximum depth found.', 'code': {'python': 'class Solution:\n    def maxDepth(self, root: Optional[TreeNode]) -> int:\n        if not root:\n            return 0\n        left_depth = self.maxDepth(root.left)\n        right_depth = self.maxDepth(root.right)\n        return 1 + max(left_depth, right_depth)\n', 'java': 'class Solution {\n    public int maxDepth(TreeNode root) {\n        if (root == null) {\n            return 0;\n        }\n        int left = maxDepth(root.left);\n        int right = maxDepth(root.right);\n        return 1 + Math.max(left, right);\n    }\n}\n', 'cpp': '#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int maxDepth(TreeNode* root) {\n        if (root == nullptr) {\n            return 0;\n        }\n        int left = maxDepth(root->left);\n        int right = maxDepth(root->right);\n        return 1 + max(left, right);\n    }\n};\n'}}, 543: {'name': 'Brute Force (Depth at Every Node)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(h)', 'explanation': 'For every node in the tree, calculate maxDepth(left) + maxDepth(right) using independent recursive depth calls.', 'code': {'python': 'class Solution:\n    def diameterOfBinaryTree(self, root: Optional[TreeNode]) -> int:\n        if not root:\n            return 0\n        def depth(node):\n            if not node:\n                return 0\n            return 1 + max(depth(node.left), depth(node.right))\n        current_dia = depth(root.left) + depth(root.right)\n        left_dia = self.diameterOfBinaryTree(root.left)\n        right_dia = self.diameterOfBinaryTree(root.right)\n        return max(current_dia, left_dia, right_dia)\n', 'java': 'class Solution {\n    public int diameterOfBinaryTree(TreeNode root) {\n        if (root == null) {\n            return 0;\n        }\n        int current = depth(root.left) + depth(root.right);\n        int left = diameterOfBinaryTree(root.left);\n        int right = diameterOfBinaryTree(root.right);\n        return Math.max(current, Math.max(left, right));\n    }\n\n    private int depth(TreeNode node) {\n        if (node == null) {\n            return 0;\n        }\n        return 1 + Math.max(depth(node.left), depth(node.right));\n    }\n}\n', 'cpp': '#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    int diameterOfBinaryTree(TreeNode* root) {\n        if (root == nullptr) {\n            return 0;\n        }\n        int current = depth(root->left) + depth(root->right);\n        int left = diameterOfBinaryTree(root->left);\n        int right = diameterOfBinaryTree(root->right);\n        return max(current, max(left, right));\n    }\n\nprivate:\n    int depth(TreeNode* node) {\n        if (node == nullptr) {\n            return 0;\n        }\n        return 1 + max(depth(node->left), depth(node->right));\n    }\n};\n'}}, 102: {'name': 'Brute Force (Depth-by-Depth Extraction)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(h)', 'explanation': 'Compute tree depth, then for each level d from 1 to depth, run a separate recursive traversal to collect all nodes at level d.', 'code': {'python': 'class Solution:\n    def levelOrder(self, root: Optional[TreeNode]) -> list[list[int]]:\n        res = []\n        if not root:\n            return res\n        def get_level(node, target_level, current_level, acc):\n            if not node:\n                return\n            if current_level == target_level:\n                acc.append(node.val)\n                return\n            get_level(node.left, target_level, current_level + 1, acc)\n            get_level(node.right, target_level, current_level + 1, acc)\n\n        def max_d(node):\n            if not node:\n                return 0\n            return 1 + max(max_d(node.left), max_d(node.right))\n\n        d = max_d(root)\n        for lvl in range(1, d + 1):\n            acc = []\n            get_level(root, lvl, 1, acc)\n            res.append(acc)\n        return res\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public List<List<Integer>> levelOrder(TreeNode root) {\n        List<List<Integer>> res = new ArrayList<>();\n        if (root == null) {\n            return res;\n        }\n        int depth = maxDepth(root);\n        for (int d = 1; d <= depth; d++) {\n            List<Integer> level = new ArrayList<>();\n            collectLevel(root, d, 1, level);\n            res.add(level);\n        }\n        return res;\n    }\n\n    private void collectLevel(TreeNode node, int target, int curr, List<Integer> acc) {\n        if (node == null) {\n            return;\n        }\n        if (curr == target) {\n            acc.add(node.val);\n            return;\n        }\n        collectLevel(node.left, target, curr + 1, acc);\n        collectLevel(node.right, target, curr + 1, acc);\n    }\n\n    private int maxDepth(TreeNode node) {\n        if (node == null) {\n            return 0;\n        }\n        return 1 + Math.max(maxDepth(node.left), maxDepth(node.right));\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<vector<int>> levelOrder(TreeNode* root) {\n        vector<vector<int>> res;\n        if (root == nullptr) {\n            return res;\n        }\n        int depth = maxDepth(root);\n        for (int d = 1; d <= depth; d++) {\n            vector<int> level;\n            collectLevel(root, d, 1, level);\n            res.push_back(level);\n        }\n        return res;\n    }\n\nprivate:\n    void collectLevel(TreeNode* node, int target, int curr, vector<int>& acc) {\n        if (node == nullptr) {\n            return;\n        }\n        if (curr == target) {\n            acc.push_back(node->val);\n            return;\n        }\n        collectLevel(node->left, target, curr + 1, acc);\n        collectLevel(node->right, target, curr + 1, acc);\n    }\n\n    int maxDepth(TreeNode* node) {\n        if (node == nullptr) {\n            return 0;\n        }\n        return 1 + max(maxDepth(node->left), maxDepth(node->right));\n    }\n};\n'}}, 98: {'name': 'Brute Force (Inorder Array Check)', 'time_complexity': 'O(n)', 'space_complexity': 'O(n)', 'explanation': 'Perform an inorder traversal to collect all node values into an array, then verify that the array is strictly strictly increasing.', 'code': {'python': 'class Solution:\n    def isValidBST(self, root: Optional[TreeNode]) -> bool:\n        values = []\n        def inorder(node):\n            if not node:\n                return\n            inorder(node.left)\n            values.append(node.val)\n            inorder(node.right)\n        inorder(root)\n        for i in range(1, len(values)):\n            if values[i] <= values[i - 1]:\n                return False\n        return True\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public boolean isValidBST(TreeNode root) {\n        List<Integer> values = new ArrayList<>();\n        inorder(root, values);\n        for (int i = 1; i < values.size(); i++) {\n            if (values.get(i) <= values.get(i - 1)) {\n                return false;\n            }\n        }\n        return true;\n    }\n\n    private void inorder(TreeNode node, List<Integer> values) {\n        if (node == null) {\n            return;\n        }\n        inorder(node.left, values);\n        values.add(node.val);\n        inorder(node.right, values);\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    bool isValidBST(TreeNode* root) {\n        vector<int> values;\n        inorder(root, values);\n        for (size_t i = 1; i < values.size(); i++) {\n            if (values[i] <= values[i - 1]) {\n                return false;\n            }\n        }\n        return true;\n    }\n\nprivate:\n    void inorder(TreeNode* node, vector<int>& values) {\n        if (node == nullptr) {\n            return;\n        }\n        inorder(node->left, values);\n        values.push_back(node->val);\n        inorder(node->right, values);\n    }\n};\n'}}, 235: {'name': 'Brute Force (Path Intersection)', 'time_complexity': 'O(n)', 'space_complexity': 'O(n)', 'explanation': 'Find the path from root to p and root to q as lists of nodes, then find the last common node along both paths.', 'code': {'python': "class Solution:\n    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':\n        path_p = []\n        curr = root\n        while curr:\n            path_p.append(curr)\n            if p.val < curr.val:\n                curr = curr.left\n            elif p.val > curr.val:\n                curr = curr.right\n            else:\n                break\n        path_q = []\n        curr = root\n        while curr:\n            path_q.append(curr)\n            if q.val < curr.val:\n                curr = curr.left\n            elif q.val > curr.val:\n                curr = curr.right\n            else:\n                break\n        lca = root\n        for a, b in zip(path_p, path_q):\n            if a is b:\n                lca = a\n            else:\n                break\n        return lca\n", 'java': 'import java.util.*;\n\nclass Solution {\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        List<TreeNode> pathP = new ArrayList<>();\n        TreeNode curr = root;\n        while (curr != null) {\n            pathP.add(curr);\n            if (p.val < curr.val) {\n                curr = curr.left;\n            } else if (p.val > curr.val) {\n                curr = curr.right;\n            } else {\n                break;\n            }\n        }\n\n        List<TreeNode> pathQ = new ArrayList<>();\n        curr = root;\n        while (curr != null) {\n            pathQ.add(curr);\n            if (q.val < curr.val) {\n                curr = curr.left;\n            } else if (q.val > curr.val) {\n                curr = curr.right;\n            } else {\n                break;\n            }\n        }\n\n        TreeNode lca = root;\n        int minLen = Math.min(pathP.size(), pathQ.size());\n        for (int i = 0; i < minLen; i++) {\n            if (pathP.get(i) == pathQ.get(i)) {\n                lca = pathP.get(i);\n            } else {\n                break;\n            }\n        }\n        return lca;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n        vector<TreeNode*> pathP;\n        TreeNode* curr = root;\n        while (curr != nullptr) {\n            pathP.push_back(curr);\n            if (p->val < curr->val) {\n                curr = curr->left;\n            } else if (p->val > curr->val) {\n                curr = curr->right;\n            } else {\n                break;\n            }\n        }\n\n        vector<TreeNode*> pathQ;\n        curr = root;\n        while (curr != nullptr) {\n            pathQ.push_back(curr);\n            if (q->val < curr->val) {\n                curr = curr->left;\n            } else if (q->val > curr->val) {\n                curr = curr->right;\n            } else {\n                break;\n            }\n        }\n\n        TreeNode* lca = root;\n        int minLen = min(pathP.size(), pathQ.size());\n        for (int i = 0; i < minLen; i++) {\n            if (pathP[i] == pathQ[i]) {\n                lca = pathP[i];\n            } else {\n                break;\n            }\n        }\n        return lca;\n    }\n};\n'}}, 236: {'name': 'Brute Force (Root-to-Node Path Finding)', 'time_complexity': 'O(n)', 'space_complexity': 'O(n)', 'explanation': 'Search the tree to build root-to-p and root-to-q node paths, then traverse both paths simultaneously to identify their last common ancestor.', 'code': {'python': "class Solution:\n    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':\n        def find_path(node, target, path):\n            if not node:\n                return False\n            path.append(node)\n            if node is target:\n                return True\n            if find_path(node.left, target, path) or find_path(node.right, target, path):\n                return True\n            path.pop()\n            return False\n\n        path_p = []\n        path_q = []\n        find_path(root, p, path_p)\n        find_path(root, q, path_q)\n\n        lca = root\n        for a, b in zip(path_p, path_q):\n            if a is b:\n                lca = a\n            else:\n                break\n        return lca\n", 'java': 'import java.util.*;\n\nclass Solution {\n    public TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {\n        List<TreeNode> pathP = new ArrayList<>();\n        List<TreeNode> pathQ = new ArrayList<>();\n        findPath(root, p, pathP);\n        findPath(root, q, pathQ);\n\n        TreeNode lca = root;\n        int minLen = Math.min(pathP.size(), pathQ.size());\n        for (int i = 0; i < minLen; i++) {\n            if (pathP.get(i) == pathQ.get(i)) {\n                lca = pathP.get(i);\n            } else {\n                break;\n            }\n        }\n        return lca;\n    }\n\n    private boolean findPath(TreeNode node, TreeNode target, List<TreeNode> path) {\n        if (node == null) {\n            return false;\n        }\n        path.add(node);\n        if (node == target) {\n            return true;\n        }\n        if (findPath(node.left, target, path) || findPath(node.right, target, path)) {\n            return true;\n        }\n        path.remove(path.size() - 1);\n        return false;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    TreeNode* lowestCommonAncestor(TreeNode* root, TreeNode* p, TreeNode* q) {\n        vector<TreeNode*> pathP;\n        vector<TreeNode*> pathQ;\n        findPath(root, p, pathP);\n        findPath(root, q, pathQ);\n\n        TreeNode* lca = root;\n        int minLen = min(pathP.size(), pathQ.size());\n        for (int i = 0; i < minLen; i++) {\n            if (pathP[i] == pathQ[i]) {\n                lca = pathP[i];\n            } else {\n                break;\n            }\n        }\n        return lca;\n    }\n\nprivate:\n    bool findPath(TreeNode* node, TreeNode* target, vector<TreeNode*>& path) {\n        if (node == nullptr) {\n            return false;\n        }\n        path.push_back(node);\n        if (node == target) {\n            return true;\n        }\n        if (findPath(node->left, target, path) || findPath(node->right, target, path)) {\n            return true;\n        }\n        path.pop_back();\n        return false;\n    }\n};\n'}}, 105: {'name': 'Brute Force (Linear Inorder Search)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(n)', 'explanation': 'At each step, take the root from preorder, search for its position in inorder linearly, and partition the subarrays recursively.', 'code': {'python': 'class Solution:\n    def buildTree(self, preorder: list[int], inorder: list[int]) -> Optional[TreeNode]:\n        if not preorder or not inorder:\n            return None\n        root_val = preorder[0]\n        root = TreeNode(root_val)\n        mid = inorder.index(root_val)\n        root.left = self.buildTree(preorder[1 : mid + 1], inorder[:mid])\n        root.right = self.buildTree(preorder[mid + 1 :], inorder[mid + 1 :])\n        return root\n', 'java': 'import java.util.Arrays;\n\nclass Solution {\n    public TreeNode buildTree(int[] preorder, int[] inorder) {\n        if (preorder.length == 0 || inorder.length == 0) {\n            return null;\n        }\n        int rootVal = preorder[0];\n        TreeNode root = new TreeNode(rootVal);\n        int mid = -1;\n        for (int i = 0; i < inorder.length; i++) {\n            if (inorder[i] == rootVal) {\n                mid = i;\n                break;\n            }\n        }\n        int[] leftPre = Arrays.copyOfRange(preorder, 1, mid + 1);\n        int[] leftIn = Arrays.copyOfRange(inorder, 0, mid);\n        int[] rightPre = Arrays.copyOfRange(preorder, mid + 1, preorder.length);\n        int[] rightIn = Arrays.copyOfRange(inorder, mid + 1, inorder.length);\n\n        root.left = buildTree(leftPre, leftIn);\n        root.right = buildTree(rightPre, rightIn);\n        return root;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\nusing namespace std;\n\nclass Solution {\npublic:\n    TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {\n        if (preorder.empty() || inorder.empty()) {\n            return nullptr;\n        }\n        int rootVal = preorder[0];\n        TreeNode* root = new TreeNode(rootVal);\n        int mid = 0;\n        for (int i = 0; i < (int)inorder.size(); i++) {\n            if (inorder[i] == rootVal) {\n                mid = i;\n                break;\n            }\n        }\n        vector<int> leftPre(preorder.begin() + 1, preorder.begin() + 1 + mid);\n        vector<int> leftIn(inorder.begin(), inorder.begin() + mid);\n        vector<int> rightPre(preorder.begin() + 1 + mid, preorder.end());\n        vector<int> rightIn(inorder.begin() + mid + 1, inorder.end());\n\n        root->left = buildTree(leftPre, leftIn);\n        root->right = buildTree(rightPre, rightIn);\n        return root;\n    }\n};\n'}}, 124: {'name': 'Brute Force (All Node Pairs Path Sum)', 'time_complexity': 'O(n^2)', 'space_complexity': 'O(h)', 'explanation': 'For each node, compute the maximum downward branch sum through left and right subtrees and update the global maximum path sum.', 'code': {'python': "class Solution:\n    def maxPathSum(self, root: Optional[TreeNode]) -> int:\n        self.max_sum = float('-inf')\n        def max_gain(node):\n            if not node:\n                return 0\n            left_gain = max(max_gain(node.left), 0)\n            right_gain = max(max_gain(node.right), 0)\n            price_newpath = node.val + left_gain + right_gain\n            if price_newpath > self.max_sum:\n                self.max_sum = price_newpath\n            return node.val + max(left_gain, right_gain)\n        max_gain(root)\n        return int(self.max_sum)\n", 'java': 'class Solution {\n    private int maxSum = Integer.MIN_VALUE;\n\n    public int maxPathSum(TreeNode root) {\n        maxGain(root);\n        return maxSum;\n    }\n\n    private int maxGain(TreeNode node) {\n        if (node == null) {\n            return 0;\n        }\n        int leftGain = Math.max(maxGain(node.left), 0);\n        int rightGain = Math.max(maxGain(node.right), 0);\n        int pathSum = node.val + leftGain + rightGain;\n        if (pathSum > maxSum) {\n            maxSum = pathSum;\n        }\n        return node.val + Math.max(leftGain, rightGain);\n    }\n}\n', 'cpp': '#include <algorithm>\n#include <climits>\nusing namespace std;\n\nclass Solution {\nprivate:\n    int maxSum = INT_MIN;\n\n    int maxGain(TreeNode* node) {\n        if (node == nullptr) {\n            return 0;\n        }\n        int leftGain = max(maxGain(node->left), 0);\n        int rightGain = max(maxGain(node->right), 0);\n        int pathSum = node->val + leftGain + rightGain;\n        if (pathSum > maxSum) {\n            maxSum = pathSum;\n        }\n        return node->val + max(leftGain, rightGain);\n    }\n\npublic:\n    int maxPathSum(TreeNode* root) {\n        maxGain(root);\n        return maxSum;\n    }\n};\n'}}, 994: {'name': 'Brute Force (Minute-by-Minute Simulation)', 'time_complexity': 'O((m * n)^2)', 'space_complexity': 'O(m * n)', 'explanation': 'Simulate minute by minute: scan the entire grid on each tick to find fresh oranges adjacent to rotten ones, mark them rotten, and repeat until no more changes occur.', 'code': {'python': 'class Solution:\n    def orangesRotting(self, grid: list[list[int]]) -> int:\n        R, C = len(grid), len(grid[0])\n        minutes = 0\n        while True:\n            to_rot = []\n            for r in range(R):\n                for c in range(C):\n                    if grid[r][c] == 1:\n                        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:\n                            nr, nc = r + dr, c + dc\n                            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == 2:\n                                to_rot.append((r, c))\n                                break\n            if not to_rot:\n                break\n            for r, c in to_rot:\n                grid[r][c] = 2\n            minutes += 1\n\n        for r in range(R):\n            for c in range(C):\n                if grid[r][c] == 1:\n                    return -1\n        return minutes\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public int orangesRotting(int[][] grid) {\n        int R = grid.length;\n        int C = grid[0].length;\n        int minutes = 0;\n        int[][] dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};\n\n        while (true) {\n            List<int[]> toRot = new ArrayList<>();\n            for (int r = 0; r < R; r++) {\n                for (int c = 0; c < C; c++) {\n                    if (grid[r][c] == 1) {\n                        for (int[] d : dirs) {\n                            int nr = r + d[0];\n                            int nc = c + d[1];\n                            if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] == 2) {\n                                toRot.add(new int[]{r, c});\n                                break;\n                            }\n                        }\n                    }\n                }\n            }\n            if (toRot.isEmpty()) {\n                break;\n            }\n            for (int[] cell : toRot) {\n                grid[cell[0]][cell[1]] = 2;\n            }\n            minutes++;\n        }\n\n        for (int r = 0; r < R; r++) {\n            for (int c = 0; c < C; c++) {\n                if (grid[r][c] == 1) {\n                    return -1;\n                }\n            }\n        }\n        return minutes;\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    int orangesRotting(vector<vector<int>>& grid) {\n        int R = grid.size();\n        int C = grid[0].size();\n        int minutes = 0;\n        vector<pair<int, int>> dirs = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};\n\n        while (true) {\n            vector<pair<int, int>> toRot;\n            for (int r = 0; r < R; r++) {\n                for (int c = 0; c < C; c++) {\n                    if (grid[r][c] == 1) {\n                        for (auto& d : dirs) {\n                            int nr = r + d.first;\n                            int nc = c + d.second;\n                            if (nr >= 0 && nr < R && nc >= 0 && nc < C && grid[nr][nc] == 2) {\n                                toRot.push_back({r, c});\n                                break;\n                            }\n                        }\n                    }\n                }\n            }\n            if (toRot.empty()) {\n                break;\n            }\n            for (auto& p : toRot) {\n                grid[p.first][p.second] = 2;\n            }\n            minutes++;\n        }\n\n        for (int r = 0; r < R; r++) {\n            for (int c = 0; c < C; c++) {\n                if (grid[r][c] == 1) {\n                    return -1;\n                }\n            }\n        }\n        return minutes;\n    }\n};\n'}}, 417: {'name': 'Brute Force (DFS From Every Cell)', 'time_complexity': 'O((m * n)^2)', 'space_complexity': 'O(m * n)', 'explanation': 'From every single cell (r, c), run a dedicated DFS traversal to check whether water can flow downwards to reach both the Pacific and Atlantic oceans.', 'code': {'python': 'class Solution:\n    def pacificAtlantic(self, heights: list[list[int]]) -> list[list[int]]:\n        R, C = len(heights), len(heights[0])\n        res = []\n        for r in range(R):\n            for c in range(C):\n                visited = set()\n                reach_p = [False]\n                reach_a = [False]\n                def dfs(cr, cc):\n                    if cr == 0 or cc == 0:\n                        reach_p[0] = True\n                    if cr == R - 1 or cc == C - 1:\n                        reach_a[0] = True\n                    if reach_p[0] and reach_a[0]:\n                        return\n                    visited.add((cr, cc))\n                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:\n                        nr, nc = cr + dr, cc + dc\n                        if 0 <= nr < R and 0 <= nc < C and (nr, nc) not in visited:\n                            if heights[nr][nc] <= heights[cr][cc]:\n                                dfs(nr, nc)\n                dfs(r, c)\n                if reach_p[0] and reach_a[0]:\n                    res.append([r, c])\n        return res\n', 'java': 'import java.util.*;\n\nclass Solution {\n    public List<List<Integer>> pacificAtlantic(int[][] heights) {\n        int R = heights.length;\n        int C = heights[0].length;\n        List<List<Integer>> res = new ArrayList<>();\n\n        for (int r = 0; r < R; r++) {\n            for (int c = 0; c < C; c++) {\n                boolean[] reach = new boolean[2]; // [0]: Pacific, [1]: Atlantic\n                boolean[][] visited = new boolean[R][C];\n                dfs(heights, r, c, reach, visited, R, C);\n                if (reach[0] && reach[1]) {\n                    res.add(Arrays.asList(r, c));\n                }\n            }\n        }\n        return res;\n    }\n\n    private void dfs(int[][] heights, int r, int c, boolean[] reach, boolean[][] visited, int R, int C) {\n        if (r == 0 || c == 0) {\n            reach[0] = true;\n        }\n        if (r == R - 1 || c == C - 1) {\n            reach[1] = true;\n        }\n        if (reach[0] && reach[1]) {\n            return;\n        }\n        visited[r][c] = true;\n        int[][] dirs = {{-1,0},{1,0},{0,-1},{0,1}};\n        for (int[] d : dirs) {\n            int nr = r + d[0];\n            int nc = c + d[1];\n            if (nr >= 0 && nr < R && nc >= 0 && nc < C && !visited[nr][nc]) {\n                if (heights[nr][nc] <= heights[r][c]) {\n                    dfs(heights, nr, nc, reach, visited, R, C);\n                }\n            }\n        }\n    }\n}\n', 'cpp': '#include <vector>\nusing namespace std;\n\nclass Solution {\npublic:\n    vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {\n        int R = heights.size();\n        int C = heights[0].size();\n        vector<vector<int>> res;\n\n        for (int r = 0; r < R; r++) {\n            for (int c = 0; c < C; c++) {\n                bool reachP = false;\n                bool reachA = false;\n                vector<vector<bool>> visited(R, vector<bool>(C, false));\n                dfs(heights, r, c, reachP, reachA, visited, R, C);\n                if (reachP && reachA) {\n                    res.push_back({r, c});\n                }\n            }\n        }\n        return res;\n    }\n\nprivate:\n    void dfs(vector<vector<int>>& heights, int r, int c, bool& reachP, bool& reachA, vector<vector<bool>>& visited, int R, int C) {\n        if (r == 0 || c == 0) {\n            reachP = true;\n        }\n        if (r == R - 1 || c == C - 1) {\n            reachA = true;\n        }\n        if (reachP && reachA) {\n            return;\n        }\n        visited[r][c] = true;\n        int dirs[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};\n        for (auto& d : dirs) {\n            int nr = r + d[0];\n            int nc = c + d[1];\n            if (nr >= 0 && nr < R && nc >= 0 && nc < C && !visited[nr][nc]) {\n                if (heights[nr][nc] <= heights[r][c]) {\n                    dfs(heights, nr, nc, reachP, reachA, visited, R, C);\n                }\n            }\n        }\n    }\n};\n'}}, 743: {'name': 'Brute Force (Bellman-Ford Relaxation)', 'time_complexity': 'O(V * E)', 'space_complexity': 'O(V)', 'explanation': 'Run Bellman-Ford by relaxing all directed edges in the network n - 1 times to find shortest paths from k to all nodes.', 'code': {'python': "class Solution:\n    def networkDelayTime(self, times: list[list[int]], n: int, k: int) -> int:\n        dist = [float('inf')] * (n + 1)\n        dist[k] = 0\n        for _ in range(n - 1):\n            for u, v, w in times:\n                if dist[u] != float('inf') and dist[u] + w < dist[v]:\n                    dist[v] = dist[u] + w\n        max_d = max(dist[1:])\n        return int(max_d) if max_d != float('inf') else -1\n", 'java': 'import java.util.Arrays;\n\nclass Solution {\n    public int networkDelayTime(int[][] times, int n, int k) {\n        int[] dist = new int[n + 1];\n        Arrays.fill(dist, Integer.MAX_VALUE);\n        dist[k] = 0;\n\n        for (int i = 1; i <= n - 1; i++) {\n            for (int[] edge : times) {\n                int u = edge[0];\n                int v = edge[1];\n                int w = edge[2];\n                if (dist[u] != Integer.MAX_VALUE && dist[u] + w < dist[v]) {\n                    dist[v] = dist[u] + w;\n                }\n            }\n        }\n        int maxDist = 0;\n        for (int i = 1; i <= n; i++) {\n            if (dist[i] == Integer.MAX_VALUE) {\n                return -1;\n            }\n            if (dist[i] > maxDist) {\n                maxDist = dist[i];\n            }\n        }\n        return maxDist;\n    }\n}\n', 'cpp': '#include <vector>\n#include <algorithm>\n#include <climits>\nusing namespace std;\n\nclass Solution {\npublic:\n    int networkDelayTime(vector<vector<int>>& times, int n, int k) {\n        vector<int> dist(n + 1, INT_MAX);\n        dist[k] = 0;\n\n        for (int i = 1; i <= n - 1; i++) {\n            for (const auto& edge : times) {\n                int u = edge[0];\n                int v = edge[1];\n                int w = edge[2];\n                if (dist[u] != INT_MAX && dist[u] + w < dist[v]) {\n                    dist[v] = dist[u] + w;\n                }\n            }\n        }\n        int maxDist = 0;\n        for (int i = 1; i <= n; i++) {\n            if (dist[i] == INT_MAX) {\n                return -1;\n            }\n            if (dist[i] > maxDist) {\n                maxDist = dist[i];\n            }\n        }\n        return maxDist;\n    }\n};\n'}}}
